#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=10

# This file lives in scripts/, so the repo is its parent directory. Everything runs from there.
REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO"

if [[ "$(id -u)" -eq 0 ]]; then
  printf '\n  Run this as your normal user, not as root.\n'
  printf '  Do not put sudo in front of it: the steps that need admin rights ask for your password themselves.\n\n'
  exit 1
fi

HUB_PORT=4780
HUB_ADDRESS=""   # set in stage 6: this computer's https address on your private network
UNIT_DIR="$HOME/.config/systemd/user"
UNIT_FILE="$UNIT_DIR/watodo-hub.service"
HUB_DATA_FILE="${XDG_DATA_HOME:-$HOME/.local/share}/watodo/watodo.json"

# ── Helpers ───────────────────────────────────────────────────────────────

_have() { command -v "$1" >/dev/null 2>&1; }

# _show "command" prints a command the way the human would type it.
_show() { printf '  %s$ %s%s\n' "$DIM" "$1" "$RESET"; }

# _run "command" CMD [ARGS] prints a command and runs it. A failure is reported, not fatal:
# the stage's check decides whether the step worked.
_run() {
  local shown="$1"; shift
  _show "$shown"
  "$@" || warn "That command reported an error (see above)."
  return 0
}

# _offer "question" "command" CMD [ARGS] shows a system-changing command and runs it only on yes.
# Returns 1 on no, so the caller can tell the human how to do it by hand.
_offer() {
  local question="$1" shown="$2"; shift 2
  _show "$shown"
  confirm "$question" || return 1
  "$@" || warn "That command reported an error (see above)."
  return 0
}

# _declined "what" "how by hand" records a skipped step so the closing summary lists it.
_declined() {
  warn "Skipped for now: $1"
  note "To do it by hand: $2"
  SKIPPED+=("$1: $2")
}

# _quit stops here. Finished steps stay finished, so the human can run the wizard again later.
_quit() {
  printf '\n'
  warn "Stopped before the rest of the setup. Nothing after this point has been done."
  say "Fix the problem above, then run: npm run setup:devices"
  say "Steps that are already done are skipped."
  if (( ${#SKIPPED[@]} )); then
    note "Still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
  exit 1
}

# _verify "what should now be true" CHECK "what to try": runs CHECK and says plainly how it went.
# On failure it prints what to try, then lets the human run the check again or quit.
_verify() {
  local what="$1" check="$2" hint="$3"
  while true; do
    if "$check"; then
      printf '  %s✓ Check passed:%s %s\n' "$GREEN" "$RESET" "$what"
      return 0
    fi
    warn "Check failed: $what, not yet."
    say "What to try: $hint"
    confirm "Run the check again?" || _quit
  done
}

# ── Checks: each returns success when the step has worked ─────────────────

# _ts_status state|name prints Tailscale's BackendState, or this computer's DNS name without its
# trailing dot, from `tailscale status --json`. Prints nothing if Tailscale is not answering.
_ts_status() {
  _have tailscale || return 0
  tailscale status --json 2>/dev/null | node -e '
    let raw = "";
    process.stdin.on("data", (chunk) => (raw += chunk));
    process.stdin.on("end", () => {
      try {
        const status = JSON.parse(raw);
        const value = process.argv[1] === "name"
          ? ((status.Self && status.Self.DNSName) || "").replace(/\.$/, "")
          : status.BackendState || "";
        process.stdout.write(value);
      } catch {
        // Not readable JSON: print nothing.
      }
    });
  ' "$1" 2>/dev/null || true
}

_tailscaled_active() { [[ "$(systemctl is-active tailscaled 2>/dev/null || true)" == active ]]; }
_check_tailscale() { _have tailscale && _tailscaled_active; }
_check_signed_in() { [[ "$(_ts_status state)" == Running ]]; }
_read_address() { HUB_ADDRESS=$(_ts_status name); [[ -n "$HUB_ADDRESS" ]]; }

_check_https() {
  local body
  body=$(curl -fsS --max-time 15 "https://$HUB_ADDRESS/hub/time" 2>/dev/null || true)
  [[ "$body" == *'"now"'* ]]
}

# The hub may need a moment after it starts, so retry for a few seconds.
_check_hub_local() {
  local body i
  for i in 1 2 3 4 5; do
    body=$(curl -fsS --max-time 3 "http://127.0.0.1:$HUB_PORT/hub/time" 2>/dev/null || true)
    [[ "$body" == *'"now"'* ]] && return 0
    sleep 1
  done
  return 1
}

# WS_CHECK opens the sync socket the phone uses. It prints a result, exits 0 on a clean open
# and close, and exits 1 on an error or after 8 seconds.
WS_CHECK='
import WebSocket from "ws";
const ws = new WebSocket(`wss://${process.env.WATODO_HUB_ADDRESS}/sync/watodo`);
const timer = setTimeout(() => {
  console.log("no answer from the sync address after 8 seconds");
  process.exit(1);
}, 8000);
ws.on("open", () => {
  console.log("sync connection opened: success");
  ws.close();
});
ws.on("close", () => {
  clearTimeout(timer);
  process.exit(0);
});
ws.on("error", (error) => {
  clearTimeout(timer);
  console.log(`sync connection failed: ${error.message}`);
  process.exit(1);
});
'
_check_ws() { WATODO_HUB_ADDRESS="$HUB_ADDRESS" node --input-type=module -e "$WS_CHECK"; }

_check_app() { curl -fsS --max-time 15 -o /dev/null "https://$HUB_ADDRESS/"; }
_check_build() { [[ -f "$REPO/dist/index.html" && -f "$REPO/dist/sw.js" ]]; }
_check_modules() { [[ -d "$REPO/node_modules/ws" && -d "$REPO/node_modules/tinybase" ]]; }
_check_hub_service() { [[ "$(systemctl --user is-active watodo-hub.service 2>/dev/null || true)" == active ]]; }
_check_linger() { [[ "$(loginctl show-user "$USER" -p Linger 2>/dev/null || true)" == "Linger=yes" ]]; }

# ── Stages ────────────────────────────────────────────────────────────────

banner "watodo: phone and computer setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Install Tailscale on this computer"
say "Tailscale links this computer and your iPhone on a private network that only your own devices can join."
if _have tailscale; then
  note "Tailscale is already installed, so the install is skipped."
elif _have pacman; then
  say "This computer runs Arch Linux, so Tailscale installs with one command."
  _offer "Install Tailscale now? It asks for your password." \
    "sudo pacman -S --needed tailscale" sudo pacman -S --needed tailscale \
    || _declined "Tailscale install" "run: sudo pacman -S --needed tailscale"
else
  say "pacman was not found, so this script cannot install Tailscale for you."
  open_url "https://tailscale.com/download/linux"
  pause "Install Tailscale from that page, then press Enter..."
fi
if _have tailscale && ! _tailscaled_active; then
  _offer "Start Tailscale's background service now, and at every boot? It asks for your password." \
    "sudo systemctl enable --now tailscaled" sudo systemctl enable --now tailscaled \
    || _declined "Tailscale background service" "run: sudo systemctl enable --now tailscaled"
fi
_verify "Tailscale is installed and its background service is running" _check_tailscale \
  "run 'pacman -Q tailscale' to see whether the package is there, and 'systemctl status tailscaled' for the service. Then run the check again."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign this computer in to Tailscale"
if _check_signed_in; then
  note "This computer is already signed in and running, so this step is skipped."
else
  say "Tailscale needs an account. A free one is enough: sign in with an account you already have, such as Google or GitHub."
  say "The --operator part lets later Tailscale commands run without sudo."
  say "The command below prints a link. Open it in your browser and approve this computer."
  _offer "Sign this computer in to Tailscale now?" \
    "sudo tailscale login --operator=$USER" sudo tailscale login --operator="$USER" \
    || _declined "Tailscale sign-in" "run: sudo tailscale login --operator=$USER"
fi
_verify "This computer is signed in to Tailscale and running" _check_signed_in \
  "run 'tailscale status'. If it says it needs a login, run the sign-in command again and open the link it prints."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Turn on HTTPS for your Tailscale network"
say "Your iPhone's app only connects to an https:// address, and Tailscale only gives this computer one once HTTPS is on."
if confirm "Did you already turn on HTTPS for your Tailscale network?"; then
  note "Already on, so this step is skipped. The next stages check it."
else
  open_url "https://login.tailscale.com/admin/dns"
  step "Turn on MagicDNS if it is not already on."
  step "Under \"HTTPS Certificates\", choose \"Enable HTTPS\"."
  step "Acknowledge the notice that machine names appear in a public certificate ledger."
  pause "Press Enter once HTTPS is enabled..."
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Build watodo"
say "This downloads the libraries watodo uses, then builds the app into the dist/ folder."
if _check_modules; then
  note "The libraries are already installed, so npm install is skipped."
else
  _offer "Install the libraries now with npm install?" "npm install" npm install \
    || _declined "npm install" "run: cd $REPO && npm install"
fi
if _check_build; then
  note "A build already exists in dist/, so the build is skipped. After code changes, run: npm run deploy"
else
  _run "npm run build" npm run build
fi
_verify "The app is built: dist/index.html and dist/sw.js exist" _check_build \
  "run 'npm run build' by hand from $REPO and read the error it prints. Fix that, then run the check again."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Install the hub so it starts by itself"
say "The hub is a small program that serves watodo and keeps a copy of your data for your phone to sync with."
note "Your data is kept in: $HUB_DATA_FILE"
NODE_BIN=$(command -v node || true)
if [[ -z "$NODE_BIN" ]]; then
  warn "node was not found on PATH, and the hub needs it."
  say "Install Node.js, then run this script again."
  _quit
fi
case "$REPO$NODE_BIN" in
  *" "*|*%*) warn "The repo or node path contains a space or a %, which the service file cannot handle."; _quit ;;
esac

UNIT_TEXT=$(<"$REPO/hub/watodo-hub.service")
UNIT_TEXT=${UNIT_TEXT//@NODE@/"$NODE_BIN"}
UNIT_TEXT=${UNIT_TEXT//@REPO@/"$REPO"}

UNIT_CHANGED=no
if [[ -f "$UNIT_FILE" && "$(<"$UNIT_FILE")" == "$UNIT_TEXT" ]]; then
  note "The service file at $UNIT_FILE is already up to date."
else
  say "The service file goes to $UNIT_FILE and reads:"
  printf '%s\n' "$UNIT_TEXT" | sed 's/^/    /'
  if confirm "Write that service file now?"; then
    mkdir -p "$UNIT_DIR"
    printf '%s\n' "$UNIT_TEXT" > "$UNIT_FILE"
    UNIT_CHANGED=yes
    printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$UNIT_FILE"
  else
    _declined "watodo hub service file" "copy hub/watodo-hub.service to $UNIT_FILE with @NODE@ and @REPO@ filled in"
    _quit
  fi
fi

if [[ "$UNIT_CHANGED" == yes ]]; then
  _offer "Reload systemd so it reads the new file?" "systemctl --user daemon-reload" \
    systemctl --user daemon-reload || true
fi
if systemctl --user is-enabled --quiet watodo-hub.service 2>/dev/null; then
  if [[ "$UNIT_CHANGED" == yes ]] || ! _check_hub_service; then
    _offer "Restart the hub so it uses the new settings?" "systemctl --user restart watodo-hub.service" \
      systemctl --user restart watodo-hub.service || true
  else
    note "The hub service is already running."
  fi
else
  _offer "Start the hub now, and at every login?" "systemctl --user enable --now watodo-hub.service" \
    systemctl --user enable --now watodo-hub.service || true
fi

if _check_linger; then
  note "Your user services already keep running after you log out."
else
  warn "Until you allow it, the hub only runs while you are logged in."
  say "This lets your user services keep running after you log out, and start at boot."
  _offer "Allow that now? It asks for your password." "sudo loginctl enable-linger $USER" \
    sudo loginctl enable-linger "$USER" \
    || _declined "hub running after logout" "run: sudo loginctl enable-linger $USER"
fi

_verify "The hub answers on this computer at http://127.0.0.1:$HUB_PORT" _check_hub_local \
  "run 'systemctl --user status watodo-hub' and read the last lines. If the port is taken, stop any hub you started by hand (npm run hub). Then run the check again."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Put the hub on your private network"
say "Tailscale Serve gives the hub an https:// address that only your own Tailscale devices can reach."
_read_address || true
if [[ -n "$HUB_ADDRESS" ]] && _check_https; then
  note "The hub is already shared on your private network, so this step is skipped."
else
  _offer "Share the hub on your private network now?" "tailscale serve --bg $HUB_PORT" \
    tailscale serve --bg "$HUB_PORT" \
    || _declined "Tailscale Serve sharing" "run: tailscale serve --bg $HUB_PORT"
fi
_verify "This computer's Tailscale address is known" _read_address \
  "check that HTTPS is on (stage 3) and that 'tailscale status' lists this computer. Then run the check again."
printf '\n    %s%s%s\n\n' "$BOLD$GREEN" "https://$HUB_ADDRESS" "$RESET"
note "This is your watodo address. You will type it on your iPhone."
_verify "The hub answers over https at https://$HUB_ADDRESS" _check_https \
  "a new HTTPS certificate can take a minute. Wait a minute, then run the check again. 'tailscale serve status' shows what is being shared."
_verify "The sync connection opens over https" _check_ws \
  "the same certificate wait applies. Syncing runs over this connection, so it has to work."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Open watodo on this computer"
say "This address keeps its own saved data, separate from anything you created earlier at a localhost address."
say "So the first-launch setup runs here once. Do it now."
open_url "https://$HUB_ADDRESS"
step "Choose a starting day, adjust anything you want, then Save."
pause "Press Enter once the setup is saved..."
_verify "watodo loads at https://$HUB_ADDRESS" _check_app \
  "wait a minute if the certificate was just issued, then run the check again. You can also open the address by hand in a browser."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Tailscale on your iPhone"
if confirm "Is Tailscale already installed, signed in and switched on at your iPhone?"; then
  note "Already done, so this step is skipped."
else
  step "Install \"Tailscale\" from the App Store."
  step "Open it and sign in with the same account you used on this computer."
  step "Allow the VPN configuration when iPhone asks."
  step "Switch Tailscale on."
  note "While it is on, a VPN icon shows on the iPhone. Only traffic to your own devices uses it."
  note "This computer cannot check the iPhone directly. Stage 9 proves it."
  pause "Press Enter once Tailscale is on on your iPhone..."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Add watodo to your iPhone's home screen"
say "Your watodo address:"
printf '\n    %s%s%s\n\n' "$BOLD$GREEN" "https://$HUB_ADDRESS" "$RESET"
if confirm "Is watodo already on your iPhone's home screen?"; then
  note "Already done, so this step is skipped."
else
  step "On the iPhone, open Safari. It must be Safari."
  step "Go to the address above. It should open straight to the Now screen with the day you set up here, with no tutorial."
  step "Tap the Share button, then \"Add to Home Screen\", then \"Add\"."
  step "Close Safari, then open watodo from its new icon."
  note "Tailscale must be switched on on the iPhone for the address to load."
  pause "Press Enter once watodo opens from its icon..."
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check that the two stay in step"
step "On the iPhone, log an activity. Watch it appear on this computer within a few seconds."
step "On this computer, log an activity. Check that it appears on the iPhone within a few seconds."
pause "Press Enter after you have tried both ways..."
while ! confirm "Did both changes show up on the other device?"; do
  warn "Check failed: the two devices are not in step yet. Check these in order:"
  note "  - Tailscale is switched on on the iPhone."
  note "  - The hub is running on this computer: systemctl --user status watodo-hub"
  note "  - The iPhone's clock is set automatically (Settings > General > Date & Time)."
  confirm "Run the two-way check again?" || _quit
  pause "Press Enter after you have tried both ways again..."
done
printf '  %s✓ Check passed:%s the two devices stay in step\n' "$GREEN" "$RESET"

finish

say "Worth remembering, from $REPO:"
note "  Update watodo after code changes:  npm run deploy"
note "  Stop the hub:                       systemctl --user stop watodo-hub"
note "  Turn the sharing off:               tailscale serve --bg $HUB_PORT off"
note "  Your data file:                     $HUB_DATA_FILE"
printf '\n'
